import sys
from collections import deque

def solve():
    input = sys.stdin.readline
    n = int(input())
    c = [input().strip() for _ in range(n)]

    in_edges = [[[] for _ in range(26)] for _ in range(n)]
    out_edges = [[[] for _ in range(26)] for _ in range(n)]

    dist = [[-1] * n for _ in range(n)]
    q = deque()

    for i in range(n):
        dist[i][i] = 0
        q.append((i, i))

    for i in range(n):
        for j, ch in enumerate(c[i]):
            if ch != "-":
                k = ord(ch) - ord("a")
                out_edges[i][k].append(j)
                in_edges[j][k].append(i)
                if dist[i][j] == -1:
                    dist[i][j] = 1
                    q.append((i, j))

    while q:
        u, v = q.popleft()
        nd = dist[u][v] + 2

        for k in range(26):
            for x in in_edges[u][k]:
                for y in out_edges[v][k]:
                    if dist[x][y] == -1:
                        dist[x][y] = nd
                        q.append((x, y))

    for row in dist:
        print(*row)

if __name__ == "__main__":
    solve()
